(function () {
  var root = document.documentElement;
  var toggle = document.getElementById('toggle');
  toggle.addEventListener('click', function () { root.classList.toggle('nav-open'); });

  document.querySelectorAll('.toc a').forEach(function (a) {
    a.addEventListener('click', function () { root.classList.remove('nav-open'); });
  });

  // 正文锚点只写入地址栏，不跳动页面
  var content = document.querySelector('.content');
  content.addEventListener('click', function (e) {
    var a = e.target.closest('a.anchor');
    if (!a) return;
    e.preventDefault();
    history.replaceState(null, '', a.getAttribute('href'));
  });

  // 关键词筛选：命中标题后保留该节内容
  var filter = document.getElementById('filter');
  var FLAT = '.content h2, .content h3';
  filter.addEventListener('input', function () {
    var q = filter.value.trim().toLowerCase();
    var heads = Array.prototype.slice.call(document.querySelectorAll(FLAT));
    heads.forEach(function (h) {
      var hit = !q || h.textContent.toLowerCase().indexOf(q) >= 0;
      h.classList.toggle('dim', !hit);
      var node = h.nextElementSibling;
      while (node && node.tagName !== 'H2' && node.tagName !== 'H3') {
        node.classList.toggle('dim', !hit);
        node = node.nextElementSibling;
      }
    });
    document.querySelectorAll('.toc a').forEach(function (a) {
      a.classList.toggle('dim', !!q && a.textContent.toLowerCase().indexOf(q) < 0);
    });
  });

  // 章节高亮跟随视口
  var links = {};
  document.querySelectorAll('.toc a').forEach(function (a) {
    links[a.getAttribute('href').slice(1)] = a;
  });
  var active = null;
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (en) {
      if (!en.isIntersecting) return;
      if (active) active.classList.remove('active');
      active = links[en.target.id] || null;
      if (active) active.classList.add('active');
    });
  }, { rootMargin: '-8% 0px -82% 0px' });
  document.querySelectorAll(FLAT).forEach(function (h) { if (links[h.id]) io.observe(h); });

  var top = document.getElementById('totop');
  top.addEventListener('click', function () {
    var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    window.scrollTo({ top: 0, behavior: reduced ? 'auto' : 'smooth' });
  });
  window.addEventListener('scroll', function () {
    top.classList.toggle('show', window.scrollY > 600);
  }, { passive: true });
})();

